rows_idx = data_rows('Membership', {'A': 'string', 'B': 'string', 'C': 'string'})
teams = {}
for r in rows_idx:
    status = cell('Membership', f'C{r}')
    if status == 'Completed':
        team = cell('Membership', f'B{r}')
        pid = cell('Membership', f'A{r}')
        if team not in teams:
            teams[team] = set()
        teams[team].add(pid)
max_count = max(len(pids) for pids in teams.values())
best_teams = sorted([t for t, pids in teams.items() if len(pids) == max_count])
result = best_teams[0]

skus = values('Opening stock', 'A2:A4')
opening = values('Opening stock', 'B2:B4')
mov_skus = values('Movements', 'A2:A13')
mov_units = values('Movements', 'C2:C13')
stocks = {}
for s, o in zip(skus, opening):
    stocks[s] = o
for s, u in zip(mov_skus, mov_units):
    stocks[s] += u
result = max(stocks, key=stocks.get)
